const ateliers = [{id:"s",titre:"Semis"},{id:"c",titre:"Compost"}];
function Fiche({ atelier, retenu, surBasculer }) {
  return <li data-id={atelier.id}><span className="titre">{atelier.titre}</span><button id={"choix-" + atelier.id} type="button" aria-pressed={retenu} onClick={() => surBasculer(atelier.id)}>{retenu ? "Retirer du choix" : "Retenir"}</button></li>;
}
function Bilan({ titres }) {
  return <section><p id="total">Choix : {titres.length}</p><p id="bilan" aria-live="polite">{titres.length === 0 ? "Aucun choix." : titres.join(", ")}</p></section>;
}
function App() {
  const [retenus, setRetenus] = useState([]);
  function basculer(id) { setRetenus(anciens => anciens.includes(id) ? anciens.filter(x => x !== id) : [...anciens,id]); }
  const titres = ateliers.filter(a => retenus.includes(a.id)).map(a => a.titre);
  return <main><ul id="liste">{ateliers.map(a => <Fiche key={a.id} atelier={a} retenu={retenus.includes(a.id)} surBasculer={() => {}} />)}</ul><Bilan titres={titres} /><p id="limite">Choix temporaires, aucune inscription.</p></main>;
}
root.render(<App />);

