function App() {
  const [titre, setTitre] = useState('');
  const [places, setPlaces] = useState('');
  const [champErreur, setChampErreur] = useState('');
  const [erreur, setErreur] = useState('');
  const [lignes, setLignes] = useState([]);
  const titreRef = useRef(null);
  const placesRef = useRef(null);
  function soumettre(event) {
    event.preventDefault();
    const nom = titre.trim();
    const nombre = Number(places);
    if (nom.length < 2) {
      setChampErreur('titre'); setErreur('Écris au moins 2 caractères.'); titreRef.current.focus(); return;
    }
    if (places.trim() === '' || !Number.isInteger(nombre) || nombre < 0 || nombre > 5) {
      setChampErreur('places'); setErreur('Choisis un entier de 0 à 5.'); titreRef.current.focus(); return;
    }
    setChampErreur(''); setErreur('');
    setLignes(avant => [...avant, {id:avant.length+1, texte:nom + ' : ' + nombre}]);
    setTitre(''); setPlaces(''); titreRef.current.focus();
  }
  return <main><h1>Liste fictive</h1><form id="formulaire" noValidate onSubmit={soumettre}><label htmlFor="titre">Titre</label><input id="titre" ref={titreRef} value={titre} onChange={e => setTitre(e.target.value)} aria-invalid={champErreur === 'titre' ? 'true' : undefined} aria-describedby="aide-titre erreur" /><p id="aide-titre">Au moins 2 caractères.</p><label htmlFor="places">Places</label><input id="places" type="number" ref={placesRef} value={places} onChange={e => setPlaces(e.target.value)} aria-invalid={champErreur === 'places' ? 'true' : undefined} aria-describedby="aide-places erreur" /><p id="aide-places">Entier de 0 à 5.</p><p id="erreur" aria-live="polite">{erreur}</p><button type="submit">Ajouter</button></form><ul id="liste">{lignes.map(ligne => <li key={ligne.id}>{ligne.texte}</li>)}</ul><p id="compte" role="status">{lignes.length} ajout(s)</p></main>;
}
root.render(<App />);

